export type ParsedAgentSpendInstruction<
  TProgram extends string = typeof DEAL_ESCROW_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    agent: TAccountMetas[0];
    mission: TAccountMetas[1];
    mandate: TAccountMetas[2];
    missionAuth: TAccountMetas[3];
    mint: TAccountMetas[4];
    vault: TAccountMetas[5];
    payeeToken: TAccountMetas[6];
    /** Required when the mandate has no payee list: the payee must be this listing's seller. */
    listing?: TAccountMetas[7] | undefined;
    /** Required with a listing: its assessor must be registered. */
    registry?: TAccountMetas[8] | undefined;
    tokenProgram: TAccountMetas[9];
  };
  data: AgentSpendInstructionData;
};

export function parseAgentSpendInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedAgentSpendInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === DEAL_ESCROW_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      agent: getNextAccount(),
      mission: getNextAccount(),
      mandate: getNextAccount(),
      missionAuth: getNextAccount(),
      mint: getNextAccount(),
      vault: getNextAccount(),
      payeeToken: getNextAccount(),
      listing: getNextOptionalAccount(),
      registry: getNextOptionalAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getAgentSpendInstructionDataDecoder().decode(instruction.data),
  };
}
